INSERT INTO `books` (`id`, `title`, `subtitle`, `isbn`, `publisher_id`, `series_id`, `publication_year`, `category`, `difficulty`, `language`, `description`, `trial_text`, `ebook_pdf_url`, `ebook_epub_url`, `cover_url`, `page_count`, `avg_rating`, `rating_count`, `view_count`, `trial_count`, `hot_score`, `is_new`, `is_deleted`, `created_at`, `updated_at`) VALUES
(1, '三体', NULL, '9787536692930', 1, 36, 2008, '科幻', '大众', 'zh-CN', '文化大革命如火如荼进行的同时。军方探寻外星文明的绝秘计划“红岸工程”取得了突破性进展。但在按下发射键的那一刻，历经劫难的叶文洁没有意识到，她彻底改变了人类的命运。地球文明向宇宙发出的第一声啼鸣，以太阳为中心，以光速向宇宙深处飞驰……四光年外，“三体文明”正苦苦挣扎——三颗无规则运行的太阳主导下的百余次毁灭与重生逼迫他们逃离母星。而恰在此时。他们接收到了地球发来的信息。在运用超技术锁死地球人的基础科学之后。三体人庞大的宇宙舰队开始向地球进发……人类的末日悄然来临。', '文化大革命如火如荼进行的同时。军方探寻外星文明的绝秘计划“红岸工程”取得了突破性进展。但在按下发射键的那一刻，历经劫难的叶文洁没有意识到，她彻底改变了人类的命运。地球文明向宇宙发出的第一声啼鸣，以太阳为中心，以光速向宇宙深处飞驰……四光年外，“三体文明”正苦苦挣扎——三颗无规则运行的太阳主导下的百余次毁灭与重生逼迫他们逃离母星。而恰在此时。他们接收到了地球发来的信息。在运用超技术锁死地球人的基础科学之后。三体人庞大的宇宙舰队开始向地球进发……人类的末日悄然来临。', '/data/book_read/三体.pdf', NULL, '/data/book_read/9787536692930.jpg', 302, 4.7, 7, 195, 58, 51752.0, 0, 0, '2026-07-01 02:03:01', '2026-07-03 16:43:34'),
(2, '流浪地球', NULL, '978-7-000-0002', 2, 2, 2000, '科幻', '大众', 'zh-CN', '太阳即将毁灭，人类推动地球离开太阳系寻找新家园。', '太阳即将毁灭，人类推动地球离开太阳系寻找新家园。
